import{_ as e,o as t,c as i,ag as n}from"./chunks/framework.D5hoimZQ.js";const p=JSON.parse('{"title":"科学日报 · 2026-10-12（生物医学）","description":"","frontmatter":{"sidebar":true},"headers":[],"relativePath":"topics/biomedicine/science-daily-2026-10-12.md","filePath":"topics/biomedicine/science-daily-2026-10-12.md"}'),r={name:"topics/biomedicine/science-daily-2026-10-12.md"};function s(c,o,a,d,l,u){return t(),i("div",null,[...o[0]||(o[0]=[n('<h1 id="科学日报-·-2026-10-12-生物医学" tabindex="-1">科学日报 · 2026-10-12（生物医学） <a class="header-anchor" href="#科学日报-·-2026-10-12-生物医学" aria-label="Permalink to &quot;科学日报 · 2026-10-12（生物医学）&quot;">​</a></h1><blockquote><p>指向仓库：<code>ScienceDaily/daily/2026-10-12.md</code> — 第35期</p></blockquote><hr><h2 id="人类心脏发育的细胞地图-以及-21-三体如何打乱它-nature" tabindex="-1">人类心脏发育的细胞地图，以及 21 三体如何打乱它（Nature） <a class="header-anchor" href="#人类心脏发育的细胞地图-以及-21-三体如何打乱它-nature" aria-label="Permalink to &quot;人类心脏发育的细胞地图，以及 21 三体如何打乱它（Nature）&quot;">​</a></h2><blockquote><p>指向仓库：<code>ScienceDaily/daily/2026-10-12.md</code> ｜ DOI: 10.1038/s41586-026-11125-y</p></blockquote><ul><li>方法：<strong>单细胞 + 空间多组学</strong>联合，在发育中的人类心脏里定义 <strong>21 个组织生态位（niche）</strong>，并据此开发分辨率无关的分类工具 <strong>TissueTypist</strong>。</li><li>结构亮点：对<strong>窦房结</strong>做高分辨空间图谱，分辨出沿<strong>线性轴</strong>排列的<strong>三种起搏细胞亚型</strong>。</li><li>互作：第一孕期起搏细胞带有**&quot;神经招引&quot;程序**，经 <strong>Eph–ephrin、semaphorin–plexin</strong> 等通路与<strong>副交感神经元</strong>互作——发育期的&quot;神经-心脏&quot;对话被具体到分子通路。</li><li>轨迹：追踪心房/心室心肌细胞成熟，发现一个<strong>脂质–代谢开关</strong>。</li><li>疾病：把图谱用于 <strong>21 三体（唐氏综合征）</strong>，定位其发育扰动 → 为<strong>先天性心脏病</strong>机制提供细胞级参照。</li><li>洞察（对本库 <code>biomedicine</code> / <code>design</code>）：这是&quot;<strong>先建完整参照系，再看扰动偏在哪</strong>&quot;的范式——21 三体不是&quot;某基因坏了&quot;，而是<strong>在一个已标定的发育坐标里读偏差</strong>。与 <code>science-daily-2026-10-11.md</code>（表型差异拆成性别轴/体型轴）同构：<strong>面对复杂表型，先问它在几条正交&quot;坐标轴&quot;上各自偏了多少。</strong></li></ul><hr><h2 id="肠道菌的一种奇数链脂肪酸-能缓解小鼠动脉粥样硬化-nature" tabindex="-1">肠道菌的一种奇数链脂肪酸，能缓解小鼠动脉粥样硬化（Nature） <a class="header-anchor" href="#肠道菌的一种奇数链脂肪酸-能缓解小鼠动脉粥样硬化-nature" aria-label="Permalink to &quot;肠道菌的一种奇数链脂肪酸，能缓解小鼠动脉粥样硬化（Nature）&quot;">​</a></h2><blockquote><p>指向仓库：<code>ScienceDaily/daily/2026-10-12.md</code> ｜ DOI: 10.1038/s41586-026-11142-x</p></blockquote><ul><li>对象：肠道菌 <em><strong>Bacteroides uniformis</strong></em> 与<strong>动脉粥样硬化</strong>。</li><li>结果：给小鼠补充 <em>B. uniformis</em> 可<strong>减轻动脉粥样硬化</strong>。</li><li>机制：起作用的是一种<strong>奇数链脂肪酸——十五烷酸（pentadecanoic acid）</strong>，它<strong>直接抑制 HMG-CoA 还原酶</strong>（胆固醇合成限速酶），促使<strong>肝脏加速清除胆固醇</strong>。</li><li>链条：肠道菌 → 特定代谢物 → 抑制限速酶 → 肝胆固醇清除↑ → 血脂/斑块↓。</li><li>边界：<strong>证据为小鼠</strong>，尚不能外推到人；但给出了<strong>明确可检验的分子靶点</strong>。</li><li>洞察（对本库 <code>biomedicine</code>）：又一个&quot;<strong>限速酶是杠杆点</strong>&quot;的实例（他汀打的是同一个 HMG-CoA 还原酶）——<strong>降脂不必新造靶点，而是给已有靶点找一条&quot;微生物产出的天然抑制剂&quot;</strong>。与 <code>science-daily-2026-10-11.md</code>（ZFP423 产热疗法，同为&quot;控制点而非全面改造&quot;）同源。</li></ul><hr><blockquote><p>📎 关联主题：<code>topics/biomedicine/index.md</code> ｜ 第35期 科学板块</p></blockquote><p>关键词：人类心脏发育、单细胞多组学、空间转录组、21 个生态位、TissueTypist、窦房结、起搏细胞亚型、Eph–ephrin、semaphorin–plexin、副交感神经元、脂质–代谢开关、21 三体、先天性心脏病；Bacteroides uniformis、十五烷酸、pentadecanoic acid、奇数链脂肪酸、HMG-CoA 还原酶、胆固醇清除、动脉粥样硬化、小鼠 关联：<code>topics/biomedicine/science-daily-2026-10-11.md</code>（ZFP423 产热疗法、狗表观遗传衰老）、<code>topics/biomedicine/2026-q3-breakthroughs.md</code>（生物医学主线）、<code>topics/biomedicine/science-daily-2026-10-10.md</code>（PI(3,4)P₂ 线粒体融合、LPS 转运）</p>',13)])])}const m=e(r,[["render",s]]);export{p as __pageData,m as default};
